use std::fs;
use std::path::{Component, Path, PathBuf};

const ROOT: &str = "/app/bloturn";

pub fn checked(p: &str) -> Result<PathBuf, String> {
    let path = Path::new(p);
    if !path.is_absolute() {
        return Err("destination must be absolute".into());
    }
    let rel = path.strip_prefix(ROOT).map_err(|_| "destination is outside bloturn")?;
    if rel.as_os_str().is_empty()
        || rel.components().any(|c| !matches!(c, Component::Normal(_)))
    {
        return Err("invalid destination".into());
    }
    let parent = path.parent().ok_or("destination has no parent")?;
    let root = fs::canonicalize(ROOT).map_err(|e| e.to_string())?;
    let real_parent = fs::canonicalize(parent).map_err(|e| e.to_string())?;
    if !real_parent.starts_with(&root) {
        return Err("destination is outside bloturn".into());
    }
    Ok(path.to_path_buf())
}
