use std::fs::{self, OpenOptions};
use std::io::{ErrorKind, Write};
use std::path::Path;
use std::sync::atomic::{AtomicU64, Ordering};

static NEXT: AtomicU64 = AtomicU64::new(0);

pub fn replace(dest: &Path, body: &[u8]) -> Result<(), String> {
    let parent = dest.parent().ok_or("destination has no parent")?;
    let name = dest.file_name().ok_or("destination has no file name")?.to_string_lossy();
    let mut last = None;
    for _ in 0..100 {
        let n = NEXT.fetch_add(1, Ordering::Relaxed);
        let tmp = parent.join(format!(".{}.finspool-{}-{}", name, std::process::id(), n));
        match OpenOptions::new().write(true).create_new(true).open(&tmp) {
            Ok(mut f) => {
                let result = (|| -> std::io::Result<()> {
                    f.write_all(body)?;
                    f.flush()?;
                    f.sync_all()?;
                    drop(f);
                    fs::rename(&tmp, dest)?;
                    fs::File::open(parent)?.sync_all()?;
                    Ok(())
                })();
                if let Err(e) = result {
                    let _ = fs::remove_file(&tmp);
                    return Err(e.to_string());
                }
                return Ok(());
            }
            Err(e) if e.kind() == ErrorKind::AlreadyExists => last = Some(e),
            Err(e) => return Err(e.to_string()),
        }
    }
    Err(last.map(|e| e.to_string()).unwrap_or_else(|| "cannot create temporary file".into()))
}
EOF

